(()=>{'use strict';const V='20260728-player-tabs-shell-logos-v1';let data=null,promise=null;const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,'');function load(){if(data)return Promise.resolve(data);if(promise)return promise;promise=fetch(`team-data/logo-map.json?v=${V}`,{cache:'default'}).then(r=>r.ok?r.json():Promise.reject()).then(d=>data=d).catch(()=>data={logos:{},aliases:{}});return promise}function find(name){if(!data)return'';const key=norm(name),aliasEntry=Object.entries(data.aliases||{}).find(([k])=>norm(k)===key),target=aliasEntry?aliasEntry[1]:name;const hit=Object.entries(data.logos||{}).find(([k])=>norm(k)===norm(target));return hit?.[1]||''}function generic(src){return !src||/^(escudo|silhueta)\.webp(?:\?|$)/i.test(String(src).split('/').pop())}function resolve(name,current=''){const mapped=find(name);return generic(current)?mapped||current||'escudo.webp':current}function fallback(img){if(!img||img.dataset.cffLogoFallback==='done')return;const mapped=find(img.dataset.teamLogo||'');if(mapped&&img.getAttribute('src')!==mapped){img.dataset.cffLogoFallback='mapped';img.src=mapped;return}img.dataset.cffLogoFallback='done';img.src='escudo.webp'}window.cffLoadTeamLogoMap=load;window.cffResolveTeamLogo=resolve;window.cffFindTeamLogo=find;document.addEventListener('error',e=>{const img=e.target;if(img?.tagName==='IMG'&&img.dataset?.teamLogo)fallback(img)},true);})();